/* M205 – Das Marketing – version allemande, générée par outils/traduction.js depuis data.js (mêmes épreuves, même ordre). a[0] = richtige Antwort. */
window.OBJ = [{"code":"M205.1","t":"Ziele des Marketings","g":"Ich kann die verschiedenen Ziele des Marketings erklären, wie den Verkauf fördern, den Marktanteil erhöhen, die Bekanntheit verbessern und ein positives Image im Markt verankern.","col":"teal","ic":"target","ch":[{"k":"qcm","q":"Was ist das Hauptziel des Marketings?","a":["Gewinn erzielen","Die Zahl der Kunden des Unternehmens senken","Die Arbeitszeiten im Lager festlegen","Die Buchhaltung ersetzen"],"ex":"Das Marketing will den Verkauf fördern, um Umsatz und Gewinn zu steigern.","ref":"Lektion 5.1"},{"k":"multi","q":"Welches sind laut Kurs die Hauptziele des Marketings?","good":["Den Marktanteil halten und erhöhen","Die Bekanntheit verbessern","Ein positives Image verankern"],"bad":["Die Qualität der Produkte senken","Die Zahl der Kunden verringern"],"ex":"Marktanteil, Bekanntheit und positives Image.","ref":"Lektion 5.1"},{"k":"qcm","q":"Was ist die «Bekanntheit» einer Marke?","a":["Die Tatsache, dass sie bekannt ist","Der Durchschnittspreis ihrer Produkte im Laden","Die Zahl ihrer Lager in der Schweiz","Der Lohn ihrer Direktoren"],"ex":"Die Bekanntheit verbessern heisst, die Marke bekannt zu machen.","ref":"Lektion 5.1"},{"k":"tf","q":"Eine wirksame Werbekampagne kann die Bekanntheit steigern und neue Kunden anziehen.","v":true,"ex":"Das ist das in Lektion 5.1 hervorgehobene Zitat.","ref":"Lektion 5.1"},{"k":"case","s":"Ein Technologieunternehmen lanciert ein neues Smartphone.","q":"Was ermöglicht ihm das Marketing laut dem Beispiel des Kurses?","a":["Erwartungen erkennen, Preis festlegen, Verkaufsort wählen und bewerben","Das Telefon ohne vorherige Kundenstudie herstellen","Das Telefon ohne Verpackung liefern, um alle Kosten zu senken","Das Telefon nur an die Mitarbeitenden des Unternehmens verkaufen"],"ex":"Gesuchte Merkmale, attraktiver Preis, strategische Verkaufsstellen, gezielte Kampagnen.","ref":"Lektion 5.1"},{"k":"order","q":"Bringen Sie die im Kurs vorgestellten Bestandteile des Marketings in die richtige Reihenfolge.","a":["Marktforschung","Segmentierung","Positionierung","Marketing-Mix (4 P)"],"ex":"Man untersucht den Markt, teilt ihn in Segmente, positioniert das Produkt und legt dann den Mix fest.","ref":"Lektion 5.1"},{"k":"match","q":"Ordnen Sie jedem Bestandteil des Marketings seine Definition zu.","p":[["Marktforschung","Bedürfnisse, Trends und Konkurrenz analysieren"],["Segmentierung","Den Markt in Kundengruppen aufteilen"],["Positionierung","Dem Produkt einen Platz im Kopf der Kunden geben"],["Marketing-Mix","Produkt, Preis, Distribution und Kommunikation kombinieren"]],"ex":"Das sind die vier Bestandteile des Kurses.","ref":"Lektion 5.1"},{"k":"qcm","q":"Was ist Segmentierung?","a":["Den Markt in Kundengruppen aufteilen","Paletten in kleine Pakete aufteilen","Die Löhne nach Abteilungen verteilen","Die Lieferanten nach Preis ordnen"],"ex":"Den Markt in Gruppen mit ähnlichen Bedürfnissen aufteilen und dann die vielversprechendsten anvisieren.","ref":"Lektion 5.1"},{"k":"case","s":"Eine Getränkemarke will vor allem Sportlerinnen und Sportler von 18 bis 30 Jahren ansprechen.","q":"Welchen Bestandteil des Marketings verwendet sie?","a":["Segmentierung und Zielgruppe","Die Kostenrechnung im Betrieb","Die Verwaltung der Sicherheitsbestände","Die permanente Inventur"],"ex":"Sie wählt eine Konsumentengruppe mit ähnlichen Bedürfnissen.","ref":"Lektion 5.1"},{"k":"tf","q":"Nur die Marketingfachleute wirken am Marketing eines Unternehmens mit.","v":false,"ex":"Alle Mitarbeitenden wirken am Marketing mit, manchmal ohne es zu wollen.","ref":"Lektion 5.2"},{"k":"multi","q":"Welche Ebenen und Bereiche des Unternehmens sind am Marketing beteiligt?","good":["Die Geschäftsleitung","Der Verkauf","Die Mitarbeitenden der Produktion","Die Verwaltung und die Dienste"],"bad":["Nur die Werbeagentur","Nur die Kunden"],"ex":"Das Marketing umfasst alle Ebenen und Bereiche des Unternehmens.","ref":"Lektion 5.2"},{"k":"case","s":"Sie beliefern einen Kunden mit einem sauberen Lastwagen, sind höflich und pünktlich.","q":"Wie wirkt Ihr Verhalten auf das Marketing?","a":["Es stärkt das positive Image des Unternehmens","Es hat nichts mit dem Marketing des Unternehmens zu tun","Es betrifft nur den Verkauf am Hauptsitz","Es senkt die Bekanntheit der Marke"],"ex":"Alle Mitarbeitenden wirken am Marketing mit, auch ohne es zu wollen.","ref":"Lektion 5.2"},{"k":"case","s":"Der Verkauf verspricht den Kunden eine Lieferung innert 24 Stunden, aber Produktion und Lager sind nicht informiert.","q":"Was ist das Problem?","a":["Die Bereiche ergänzen sich nicht","Die Frist ist für die Kunden zu lang","Die Geschäftsleitung muss liefern","Es gibt kein Problem"],"ex":"Je besser sich Ebenen und Bereiche ergänzen, desto erfolgreicher ist das Unternehmen.","ref":"Lektion 5.2"},{"k":"qcm","q":"Was ist der «Marktanteil»?","a":["Der Anteil des Unternehmens an den Verkäufen des Marktes","Die Zahl der Aktien, die jede Mitarbeiterin besitzt","Die belegte Verkaufsfläche in einem Einkaufszentrum","Der Prozentsatz des Rabatts für die Kunden"],"ex":"Den Marktanteil zu halten und zu erhöhen ist ein Ziel des Marketings.","ref":"Lektion 5.1"},{"k":"case","s":"Ein Unternehmen verkaufte 20 % der Sportschuhe des Landes. Ein Jahr später verkauft es 25 %.","q":"Welches Ziel des Marketings hat es erreicht?","a":["Seinen Marktanteil erhöhen","Seine Transportkosten senken","Die Ergonomie seines Lagers verbessern","Den Lohn seiner Verkäufer senken"],"ex":"Sein Anteil an den Verkäufen des Marktes ist gestiegen.","ref":"Lektion 5.1"},{"k":"qcm","q":"Was ist Positionierung?","a":["Der Platz des Produkts im Kopf der Kunden","Der Standort der Paletten im Lager","Der Rang des Unternehmens in einer Rangliste","Die Position des Logos auf der Verpackung"],"ex":"Sie schafft ein klares und attraktives Bild.","ref":"Lektion 5.1"},{"k":"case","s":"Eine Uhrenmarke will als Symbol für Luxus und Schweizer Präzision wahrgenommen werden.","q":"Um welchen Bestandteil des Marketings handelt es sich?","a":["Die Positionierung","Die Segmentierung","Die Distribution","Die Inventur"],"ex":"Die Positionierung legt Platz und Bild des Produkts im Kopf der Kunden fest.","ref":"Lektion 5.1"},{"k":"odd","q":"Was ist laut Kurs kein Ziel des Marketings?","a":["Die Qualität der Dienstleistungen senken","Den Marktanteil erhöhen","Die Bekanntheit verbessern","Ein positives Image verankern"],"ex":"Die drei anderen sind die Hauptziele des Kurses.","ref":"Lektion 5.1"},{"k":"fill","q":"Das Marketing will den Verkauf fördern, um den Umsatz und den ___ zu steigern.","a":["Gewinn","Bestand","Personalbestand","Mietzins"],"ex":"Gewinn zu erzielen ist das Hauptziel.","ref":"Lektion 5.1"},{"k":"sort","q":"Welches Ziel des Marketings verfolgt diese Massnahme vor allem?","c":["Bekanntheit","Positives Image","Marktanteil"],"it":[["Plakate, um eine neue Marke bekannt zu machen",0],["Das ökologische Engagement hervorheben",1],["Kunden eines Konkurrenten gewinnen",2],["Radiowerbung für einen neuen Namen",0],["Einen lokalen Verein unterstützen",1],["Ein günstigeres Angebot als die Konkurrenz machen",2]],"ex":"Bekannt werden, gut wahrgenommen werden, Konkurrenten Verkäufe abnehmen.","ref":"Lektion 5.1"},{"k":"tf","q":"Der vom Marketing angestrebte Gewinn zeigt sich im Preis der Produkte oder Dienstleistungen.","v":true,"ex":"Der Kurs sagt es.","ref":"Lektion 5.1"},{"k":"case","s":"Eine enge Zusammenarbeit zwischen Verkauf und Produktion erlaubt, genau das herzustellen, was die Kunden erwarten.","q":"Welche Folge leitet der Kurs daraus ab?","a":["Mehr Zufriedenheit und Verkäufe","Weniger Verkäufe, aber mehr Bestand","Keine Folge für die Kunden","Zwingend höhere Verkaufspreise"],"ex":"Konkretes Beispiel aus Lektion 5.2.","ref":"Lektion 5.2"},{"k":"qcm","q":"Was ist laut Kurs Marketing?","a":["Massnahmen zur Förderung des Angebots","Die Kontrolle der Waren im Wareneingang","Die Planung der Liefertouren des Tages","Die Berechnung der Sicherheitsbestände im Lager"],"ex":"Alle Massnahmen und Strategien, um seine Produkte oder Dienstleistungen zu fördern und die Bedürfnisse zu erfüllen.","ref":"Lektion 5.1"},{"k":"case","s":"Ein Kunde beklagt sich in den sozialen Netzwerken, dass ein Kurier Ihres Unternehmens unhöflich war.","q":"Welches Ziel des Marketings ist gefährdet?","a":["Das positive Image des Unternehmens","Der Marktanteil des Konkurrenten","Der Sicherheitsbestand des Lagers","Der Preis der Rohstoffe"],"ex":"Alle Mitarbeitenden prägen das Image des Unternehmens.","ref":"Lektion 5.2"},{"k":"case","s":"Ein neuer E-Bike-Hersteller ist der Öffentlichkeit noch unbekannt.","q":"Welches Ziel des Marketings muss er zuerst anstreben?","a":["Seine Bekanntheit verbessern","Seinen Marktanteil verringern","Seine Preise erhöhen","Seine Verkaufsstellen schliessen"],"ex":"Bevor man verkauft, muss man bekannt werden.","ref":"Lektion 5.1"}]},{"code":"M205.2","t":"Angebot und Nachfrage","g":"Ich kann die Wirkung von Angebot und Nachfrage auf die Preise der Produkte beschreiben und konkrete Beispiele nennen, wie Preisschwankungen durch reiche Ernten oder Wetterereignisse.","col":"indigo","ic":"scale","ch":[{"k":"match","q":"Ordnen Sie jeder Situation die Wirkung auf den Preis zu (der andere Faktor bleibt stabil).","p":[["Das Angebot steigt","Der Preis sinkt"],["Das Angebot sinkt","Der Preis steigt"],["Die Nachfrage steigt","Der Preis klettert"],["Die Nachfrage sinkt","Der Preis fällt"]],"ex":"Das ist die Bemerkung aus Lektion 5.3.","ref":"Lektion 5.3"},{"k":"case","s":"Eine aussergewöhnliche Salaternte schafft ein Überangebot.","q":"Was geschieht mit dem Preis?","a":["Er sinkt stark","Er steigt stark","Er bleibt genau gleich","Er wird allein von den Gemüsebauern festgelegt"],"ex":"Das Angebot übersteigt die Nachfrage: Die Grossverteiler machen Aktionen, und der Salat wird sehr günstig.","ref":"Lektion 5.3.1"},{"k":"case","s":"Trotz der Aktionen beim Salat haben die Gemüsebauern noch zu viel Ware.","q":"Welche Folge beschreibt der Kurs?","a":["Sie vernichten einen Teil der Ernte","Sie erhöhen ihre Verkaufspreise","Sie verkaufen alles an einem einzigen Tag","Sie exportieren die ganze Ernte nach Asien"],"ex":"Das Angebot übertraf die Nachfrage deutlich: enttäuschende Gewinne und Vernichtung eines Teils der Produktion.","ref":"Lektion 5.3.1"},{"k":"case","s":"Hagel zerstört einen grossen Teil der Salaternte.","q":"Welche Wirkung auf den Preis?","a":["Er steigt","Er sinkt","Er ändert sich nicht","Er wird gratis"],"ex":"Begrenztes Angebot: Die Konsumenten sind bereit, mehr zu bezahlen.","ref":"Lektion 5.3.1"},{"k":"multi","q":"Welche Wetterereignisse können die Ernte verringern und die Preise steigen lassen?","good":["Frost","Hagel","Anhaltender Regen"],"bad":["Eine aussergewöhnliche Ernte","Ideales Wetter"],"ex":"Der Kurs nennt Frost, Hagel und anhaltenden Regen.","ref":"Lektion 5.3.1"},{"k":"qcm","q":"Wie können die Erdölstaaten den Ölpreis steigen lassen?","a":["Indem sie weniger produzieren","Indem sie jeden Monat mehr produzieren","Indem sie ihre Exportabgaben senken","Indem sie den Kunden mehr Erdöl verkaufen"],"ex":"Weniger Produktion = kleineres Angebot = höhere Preise.","ref":"Lektion 5.3.1"},{"k":"tf","q":"Wenn die Erdölstaaten mehr Erdöl fördern, sinkt der Preis tendenziell.","v":true,"ex":"Mehr Angebot, stabile Nachfrage: Der Preis sinkt.","ref":"Lektion 5.3.1"},{"k":"case","s":"In Mexiko steigt die Nachfrage nach Mais zur Herstellung von Biotreibstoffen stark.","q":"Welche Wirkung beschreibt der Kurs?","a":["Der Tortillapreis hat sich verdoppelt","Der Preis der Tortillas hat sich halbiert","Der Mais ist gratis geworden","Die Tortillas wurden verboten"],"ex":"Die internationale Nachfrage hat den Preis verdoppelt; die Regierung musste eingreifen.","ref":"Lektion 5.3.2"},{"k":"qcm","q":"Was geschieht, wenn die Nachfrage ohne genügende Produktion steigt?","a":["Die Preise steigen","Die Preise sinken","Die Preise bleiben stabil","Die Lager quellen über"],"ex":"Steigende Nachfrage, ungenügendes Angebot: Die Preise steigen.","ref":"Lektion 5.3.2"},{"k":"sort","q":"Wird der Preis eher steigen oder sinken?","c":["Steigen","Sinken"],"it":[["Frühlingsfrost bei den Aprikosen",0],["Rekordernte bei den Äpfeln",1],["Grosse Nachfrage nach Masken mitten in einer Epidemie",0],["Ende der Epidemie, Masken im Überschuss",1],["Die Förderländer drosseln die Erdölförderung",0],["Weniger Touristen für die Hotels in der Nebensaison",1]],"ex":"Weniger Angebot oder mehr Nachfrage: Preis steigt. Mehr Angebot oder weniger Nachfrage: Preis sinkt.","ref":"Lektion 5.3"},{"k":"case","s":"Nach der Gesundheitskrise waren Masken in den Schweizer Geschäften in sehr grosser Menge vorhanden.","q":"Was ist mit ihrem Preis geschehen?","a":["Er ist gesunken","Er hat sich verdoppelt","Er ist gleich geblieben","Er wurde auf 10 Franken festgelegt"],"ex":"Der im Kurs zitierte Artikel spricht von einem Rückgang von 1 Franken auf 40 Rappen pro Stück.","ref":"Lektion 5.3 · Beispiel"},{"k":"tf","q":"Ein Rückgang der Nachfrage bei stabilem Angebot lässt die Preise steigen.","v":false,"ex":"Sinkende Nachfrage, stabiles Angebot: Der Preis sinkt.","ref":"Lektion 5.3"},{"k":"fill","q":"Wenn das Angebot sinkt und die Nachfrage stabil bleibt, ___ der Preis.","a":["steigt","sinkt","verschwindet","stabilisiert sich"],"ex":"Bemerkung aus Lektion 5.3.","ref":"Lektion 5.3"},{"k":"order","q":"Bringen Sie die für den Salat beschriebene Abfolge in die richtige Reihenfolge.","a":["Aussergewöhnliche Ernte","Überangebot","Aktionen der Grossverteiler","Sehr tiefe Preise","Vernichtung eines Teils der Produktion"],"ex":"Das Überangebot lässt Preise und Gewinne fallen.","ref":"Lektion 5.3.1"},{"k":"case","s":"Vor Weihnachten wollen alle dieselbe Spielkonsole, aber der Hersteller liefert wenige.","q":"Was geschieht mit dem Wiederverkaufspreis?","a":["Er klettert","Er sinkt","Er wird per Gesetz festgelegt","Er bewegt sich nie"],"ex":"Grosse Nachfrage, begrenztes Angebot: Preis steigt.","ref":"Lektion 5.3.2"},{"k":"odd","q":"Welche Situation lässt den Preis nicht steigen?","a":["Eine Rekordernte","Ein starker Frost","Eine stark steigende Nachfrage","Eine absichtlich gedrosselte Produktion"],"ex":"Eine Rekordernte erhöht das Angebot: Der Preis sinkt.","ref":"Lektion 5.3"},{"k":"qcm","q":"Warum musste die mexikanische Regierung eingreifen?","a":["Das Nationalgericht wurde unerschwinglich","Die Tortillas waren zu billig","Der Mais liess sich gar nicht mehr verkaufen","Biotreibstoffe waren verboten"],"ex":"Die Verdoppelung des Preises machte die Tortillas für viele Mexikaner unerschwinglich.","ref":"Lektion 5.3.2"},{"k":"case","s":"Ein sehr milder Winter senkt die Nachfrage nach Brennholz stark.","q":"Welche Wirkung auf den Holzpreis?","a":["Er sinkt","Er klettert","Er verdoppelt sich","Er ändert sich nicht"],"ex":"Sinkende Nachfrage, stabiles Angebot: Preis sinkt.","ref":"Lektion 5.3"},{"k":"multi","q":"Welche Akteure können das Angebot beeinflussen?","good":["Das Wetter","Die Produzenten","Die Erdölstaaten"],"bad":["Die Farbe der Verpackungen","Der Name des Geschäfts"],"ex":"Ernten, Produktionsentscheide und gewollte Steuerung des Angebots.","ref":"Lektion 5.3.1"},{"k":"tf","q":"2020 rutschte der Ölpreis kurzzeitig ins Negative.","v":true,"ex":"Das ist eines der in Lektion 5.3 zitierten Artikelbeispiele: Die Nachfrage war eingebrochen.","ref":"Lektion 5.3 · Beispiel"},{"k":"case","s":"Ihr Lager führt Regenschirme. Der Wetterbericht kündigt drei Wochen Regen an.","q":"Wie wird sich die Nachfrage nach Regenschirmen wahrscheinlich entwickeln?","a":["Sie wird steigen","Sie wird aufhören","Sie wird sinken","Sie bleibt null"],"ex":"Das Wetter beeinflusst die Nachfrage: Man muss den Bestand planen.","ref":"Lektion 5.3.2"},{"k":"qcm","q":"Was bedeutet ein «Überangebot»?","a":["Mehr Ware als Käufer","Weniger Ware als Käufer","Eine zu teure Ware","Eine verbotene Ware"],"ex":"Das Angebot übersteigt die Nachfrage.","ref":"Lektion 5.3.1"},{"k":"case","s":"Anhaltender Regen beschädigt in der Schweiz den ganzen Juni die Erdbeeren.","q":"Was werden die Konsumenten laut Kurs tun?","a":["Mehr bezahlen oder importierte Erdbeeren wählen","Die Schweizer Erdbeeren günstiger kaufen als vorher","Die beschädigten Erdbeeren gratis erhalten","Nie mehr im Leben Erdbeeren kaufen"],"ex":"Begrenztes lokales Angebot: höhere Preise, aber der Import bietet eine Auswahl.","ref":"Lektion 5.3.1"},{"k":"qcm","q":"Was lässt beim Gesetz von Angebot und Nachfrage den Preis schwanken?","a":["Angebot und Nachfrage im Verhältnis","Allein der Wille des Verkäufers","Der Wochentag, an dem man kauft","Die Farbe und Form des Produkts"],"ex":"Der Preis entwickelt sich nach dem Verhältnis von Angebot und Nachfrage.","ref":"Lektion 5.3"},{"k":"case","s":"Ein Lieferant kündigt Ihnen an, dass er wegen eines weltweiten Chipmangels dieses Jahr weniger Scanner liefern wird.","q":"Womit müssen Sie rechnen?","a":["Mit höheren Preisen und längeren Fristen","Mit tieferen Preisen und überquellenden Lagern","Mit keiner Änderung von Preis und Frist","Mit einer Gratislieferung der Scanner"],"ex":"Kleineres Angebot, stabile Nachfrage: Die Preise steigen.","ref":"Lektion 5.3.1"}]},{"code":"M205.3","t":"Die Globalisierung","g":"Ich verstehe, wie die Globalisierung die Wirkung des lokalen Angebots auf die Preise begrenzt, und kann Beispiele importierter Produkte nennen, die lokale Märkte beeinflussen.","col":"violet","ic":"globe","ch":[{"k":"qcm","q":"Wie begrenzt die Globalisierung die Wirkung einer schlechten lokalen Ernte?","a":["Man kann das Produkt importieren","Sie verbietet Obstimporte","Sie verdoppelt immer die lokalen Preise","Sie beseitigt die Nachfrage der Kunden"],"ex":"Die Konsumenten können zwischen teureren lokalen und günstigeren importierten Produkten wählen.","ref":"Lektion 5.3.1"},{"k":"case","s":"Schweizer Salate sind nach dem Hagel selten und teuer. Das Geschäft bietet auch Salate aus Spanien an.","q":"Welche Wahl hat der Konsument?","a":["Lokal und teurer oder importiert","Keine Wahl: Er muss den lokalen Preis bezahlen","Nur Gratissalate vom Bauern","Nur tiefgekühlte Salate"],"ex":"Das ist das Beispiel des Kurses.","ref":"Lektion 5.3.1"},{"k":"tf","q":"Dank der Globalisierung lässt eine schlechte lokale Ernte die Preise immer explodieren.","v":false,"ex":"Der Import begrenzt den Preisanstieg.","ref":"Lektion 5.3.1"},{"k":"case","s":"Die weltweite Nachfrage nach Mais für Biotreibstoffe steigt.","q":"Was zeigt das Beispiel Mexikos?","a":["Eine internationale Nachfrage kann lokale Preise steigen lassen","Lokale Preise hängen nie davon ab, was im Ausland geschieht","Mexikanischer Mais kann nicht in andere Länder exportiert werden","Biotreibstoffe lassen den Maispreis immer sinken"],"ex":"Die internationale Nachfrage hat den Preis der Tortillas verdoppelt.","ref":"Lektion 5.3.2"},{"k":"multi","q":"Welche importierten Produkte beeinflussen oft die lokalen Schweizer Märkte?","good":["Obst und Gemüse ausserhalb der Saison","In Asien hergestellte Kleider","Elektronik","Erdöl"],"bad":["Leitungswasser","Auf dem eigenen Dach erzeugter Solarstrom"],"ex":"Diese Produkte kommen aus dem Ausland und drücken auf die lokalen Preise.","ref":"Lektion 5.3 · Beispiele (nicht im Kursmaterial)"},{"k":"case","s":"Ein Schweizer Tomatenproduzent verkauft das Kilo für 4 Franken. Daneben werden importierte Tomaten für 2.50 Franken verkauft.","q":"Welche Wirkung hat der Import auf den lokalen Produzenten?","a":["Er begrenzt den Preis, den er verlangen kann","Er erlaubt ihm, seinen Preis zu verdoppeln","Er hat keine Wirkung auf seine Verkäufe","Er verbietet den Verkauf seiner Tomaten"],"ex":"Die Konkurrenz der Importprodukte drückt auf den lokalen Preis.","ref":"Lektion 5.3.1"},{"k":"qcm","q":"Was ist Globalisierung?","a":["Die Öffnung des Handels zwischen Ländern","Die Schliessung der Grenzen für Waren","Die ausschliesslich lokale Produktion","Die Abschaffung des internationalen Transports"],"ex":"Sie öffnet neue Märkte und ermöglicht Importe.","ref":"Lektion 5.3 · Lektion 4.1.1"},{"k":"match","q":"Ordnen Sie jeder Situation ihre Wirkung auf den lokalen Markt zu.","p":[["Import von günstigem Obst","Druck nach unten auf die lokalen Preise"],["Grosse ausländische Nachfrage nach einem lokalen Produkt","Steigende lokale Preise"],["Schlechte Ernte durch Import ausgeglichen","Begrenzter Preisanstieg"]],"ex":"Der lokale Markt hängt auch vom weltweiten Angebot und von der weltweiten Nachfrage ab.","ref":"Lektion 5.3"},{"k":"case","s":"Ihr Lager nimmt mitten im Winter jede Woche Lastwagen mit Früchten aus Spanien und Marokko entgegen.","q":"Was ermöglicht diese internationale Logistik?","a":["Das ganze Jahr Früchte anbieten","Die Schweizer Produktion abschaffen","Die Preise der Schweizer Früchte erhöhen","Jede Kontrolle im Wareneingang vermeiden"],"ex":"Die Globalisierung erweitert das Angebot über die lokale Saison hinaus.","ref":"Lektion 5.3 · Beispiel (nicht im Kursmaterial)"},{"k":"sort","q":"Lokale Wirkung oder Wirkung der Globalisierung?","c":["Lokales Angebot","Weltweites Angebot"],"it":[["Apfelernte im Wallis",0],["Bananen aus Ecuador",1],["Milch von einem Hof der Region",0],["In Asien hergestellte Telefone",1],["Käse aus der Dorfkäserei",0],["Erdöl aus dem Nahen Osten",1]],"ex":"Ein Teil des Angebots kommt von anderswo und beeinflusst den lokalen Preis.","ref":"Lektion 5.3 · Beispiele (nicht im Kursmaterial)"},{"k":"order","q":"Bringen Sie die Abfolge des mexikanischen Beispiels in die richtige Reihenfolge.","a":["Weltweite Nachfrage nach Biotreibstoffen","Steigende Nachfrage nach Mais","Steigender Maispreis","Verdoppelung des Tortillapreises","Eingreifen der Regierung"],"ex":"Eine ferne Nachfrage hat ein lokales Gericht getroffen.","ref":"Lektion 5.3.2"},{"k":"tf","q":"Lokale Preise können davon abhängen, was am anderen Ende der Welt geschieht.","v":true,"ex":"Beispiele: mexikanischer Mais, Erdöl.","ref":"Lektion 5.3"},{"k":"odd","q":"Welches Element gehört nicht zu den Wirkungen der Globalisierung auf die Preise?","a":["Das Verbot jedes importierten Produkts","Der Import günstigerer Produkte","Die Konkurrenz zwischen Produktionsländern","Die ausländische Nachfrage nach lokalen Produkten"],"ex":"Die Globalisierung erleichtert im Gegenteil die Importe.","ref":"Lektion 5.3"},{"k":"fill","q":"Die Globalisierung erlaubt, Produkte zu ___, wenn das lokale Angebot fehlt.","a":["importieren","verbieten","vernichten","verstecken"],"ex":"Das begrenzt den Preisanstieg.","ref":"Lektion 5.3.1"},{"k":"case","s":"Ein Schweizer Möbelhersteller sieht importierte Möbel kommen, die halb so teuer sind.","q":"Welche Strategie kann ihm helfen, im Markt zu bleiben?","a":["Auf Qualität, Service und Nähe setzen","Die Preise weiter erhöhen, ohne das Angebot zu ändern","Die importierten Möbel aus Asien genau kopieren","Jede Werbung einstellen, um Geld zu sparen"],"ex":"Gegenüber dem Import muss sich der lokale Produzent abheben.","ref":"Lektion 5.3 · Strategie (nicht im Kursmaterial)"},{"k":"qcm","q":"Warum sind importierte Produkte oft günstiger?","a":["Die Produktionskosten sind anderswo tiefer","Der internationale Transport ist gratis","Sie sind immer von besserer Qualität","Die Schweiz besteuert keine Importe"],"ex":"Tiefere Kosten gleichen den Transport oft aus.","ref":"Lektion 5.3 · (nicht im Kursmaterial)"},{"k":"case","s":"Die chinesische Nachfrage nach Schweizer Käse steigt stark.","q":"Welche Wirkung ist auf den Preis in der Schweiz möglich?","a":["Er kann steigen","Er sinkt zwingend","Er kann sich nicht ändern","Er wird von China festgelegt"],"ex":"Wie beim Mais lässt eine ausländische Nachfrage die lokalen Preise steigen.","ref":"Lektion 5.3.2"},{"k":"multi","q":"Welche Wirkungen hat die Globalisierung für Logistiker/-innen?","good":["Mehr Importe im Wareneingang","Zollformalitäten","Längere Transporte"],"bad":["Weniger auszufüllende Dokumente","Keine Konkurrenz mehr"],"ex":"Der Weltmarkt verlangt eine internationale Logistik.","ref":"Lektion 5.3 · (nicht im Kursmaterial)"},{"k":"case","s":"In Asien importierte Kleider werden in Schweizer Geschäften sehr günstig verkauft.","q":"Welche Wirkung haben sie auf Schweizer Kleiderhersteller?","a":["Sie stehen einer starken Konkurrenz gegenüber","Sie können ihre Preise ohne Risiko erhöhen","Sie werden automatisch ein Monopol","Sie haben keinen Konkurrenten mehr auf dem Markt"],"ex":"Importierte Produkte drücken auf lokale Märkte.","ref":"Lektion 5.3"},{"k":"tf","q":"Die Globalisierung öffnet Schweizer Unternehmen neue Märkte.","v":true,"ex":"Das ist auch einer der Gründe für Marktforschung.","ref":"Lektion 4.1.1"},{"k":"qcm","q":"Was bringt der Import dem Schweizer Konsumenten?","a":["Mehr Auswahl und oft tiefere Preise","Immer teurere Produkte als die lokalen","Weniger Auswahl im Laden","Keinen Unterschied zum Inland"],"ex":"Der Konsument kann zwischen lokal und importiert wählen.","ref":"Lektion 5.3.1"},{"k":"case","s":"Ein kalter Frühling verringert die Spargelproduktion in der Schweiz, aber die Regale bleiben voller Spargeln aus Peru.","q":"Was geschieht mit den Spargelpreisen im Laden?","a":["Der Anstieg bleibt dank Import begrenzt","Sie verdoppeln sich, weil das Schweizer Angebot fehlt","Sie werden für alle Kunden gratis","Sie werden jede Woche vom Staat festgelegt"],"ex":"Der Import begrenzt die Wirkung des lokalen Angebots auf die Preise.","ref":"Lektion 5.3.1"},{"k":"case","s":"Ein Kunde fragt Sie am Schalter, warum Erdbeeren im Winter günstiger sind als im Mai.","q":"Was antworten Sie?","a":["Sie stammen aus Ländern mit günstiger Produktion","Wintererdbeeren wachsen in der Schweiz viel besser","Der Preis wird jeden Monat vom Bund festgelegt","Das ist einfach ein Preisfehler des Geschäfts"],"ex":"Die Globalisierung beeinflusst die lokalen Preise.","ref":"Lektion 5.3"},{"k":"qcm","q":"Warum wird das Beispiel Mexikos im Kurs genannt?","a":["Die Wirkung fremder Nachfrage auf lokale Preise","Es zeigt, dass Mais auf den Märkten keinen Wert hat","Es zeigt, dass Biotreibstoffe in Mexiko verboten sind","Es zeigt, dass das Angebot nie eine Wirkung auf die Preise hat"],"ex":"Es ist das Beispiel für die Wirkung der Nachfrage.","ref":"Lektion 5.3.2"},{"k":"case","s":"Ihr Unternehmen importiert seine Verpackungskartons aus einem Nachbarland, weil sie dort günstiger sind.","q":"Was zeigt dieser Entscheid?","a":["Das Auslandsangebot beeinflusst den Einkauf","Schweizer Kartons sind nicht zu finden","Die Globalisierung hat keine Wirkung auf Unternehmen","Das Gesetz schreibt vor, im Ausland zu kaufen"],"ex":"Auch Unternehmen vergleichen das lokale und das importierte Angebot.","ref":"Lektion 5.3"}]},{"code":"M205.4","t":"Der Marketing-Mix","g":"Ich kann die vier Elemente des Marketing-Mix (Produkt, Preis, Distribution, Kommunikation) und ihre Bedeutung in der Marketingstrategie eines Unternehmens erklären.","col":"coral","ic":"grid4","ch":[{"k":"multi","q":"Welches sind die 4 P des Marketing-Mix?","good":["Produkt","Preis","Distribution (Place)","Kommunikation (Promotion)"],"bad":["Personal","Palette"],"ex":"Product, Price, Place, Promotion.","ref":"Lektion 5.4"},{"k":"match","q":"Ordnen Sie jedem P seinen englischen Namen zu.","p":[["Produkt","Product"],["Preis","Price"],["Distribution","Place"],["Kommunikation","Promotion"]],"ex":"Das sind die 4 P des Marketing-Mix.","ref":"Lektion 5.4"},{"k":"multi","q":"Womit befasst sich das «P» Produkt?","good":["Sortimentsstrategie","Technische Merkmale","Design","Verpackung"],"bad":["Ausverkauf","Öffentlichkeitsarbeit"],"ex":"Der Kurs nennt Sortimentsstrategie, technische Merkmale, Design und Verpackung.","ref":"Lektion 5.4"},{"k":"multi","q":"Welche Faktoren beeinflussen den Preis eines Produkts?","good":["Forschungsausgaben","Art des Produkts","Rohstoffkosten","Produktionskosten","Vermarktung"],"bad":["Farbe des Lastwagens","Alter des Direktors"],"ex":"Das sind die Faktoren des Kurses.","ref":"Lektion 5.4"},{"k":"multi","q":"Mit welchen Preisinstrumenten kann der Detailhändler seinen Umsatz beeinflussen?","good":["Einführungspreis","Rabatt","Promotion","Ausverkauf","Aktionen"],"bad":["Inventur","Lieferschein"],"ex":"Das sind die im Kurs genannten Instrumente.","ref":"Lektion 5.4"},{"k":"qcm","q":"Zu welchem Preis muss man laut Kurs ein Produkt verkaufen?","a":["Zu einem fairen Preis","Zum höchstmöglichen Preis","Zum tiefsten Preis auf dem Markt","Zu einem täglich zufällig festgelegten Preis"],"ex":"Weder zu teuer noch zu billig.","ref":"Lektion 5.4"},{"k":"qcm","q":"Wovon hängt die Wahl des Werbeträgers hauptsächlich ab?","a":["Vom verfügbaren Budget","Von der Zahl der Mitarbeitenden","Vom Wetter der Woche","Von der Grösse des Parkplatzes"],"ex":"Der Kurs sagt es.","ref":"Lektion 5.4"},{"k":"multi","q":"Was umfasst das «P» Promotion?","good":["Aussenwerbung","Verkaufsförderung am Verkaufspunkt","Öffentlichkeitsarbeit"],"bad":["Rohstoffkosten","Sortimentsstrategie"],"ex":"Alle Kommunikationsmassnahmen, um eine Marke, ein Produkt oder eine Dienstleistung zu fördern.","ref":"Lektion 5.4"},{"k":"qcm","q":"Welche Fragen stellt man sich beim «P» Place (Distribution)?","a":["Wer die Käufer sind und wie man sie erreicht","Welche Farbe die Verpackung des Produkts erhält","Was die verwendeten Rohstoffe kosten","Welcher Slogan in der nächsten Kampagne verwendet wird"],"ex":"Direktverkauf oder Handel, und wo das Produkt im Sortiment platziert wird.","ref":"Lektion 5.4"},{"k":"sort","q":"Zu welchem P gehört jeder Entscheid?","c":["Produkt","Preis","Distribution","Promotion"],"it":[["Die Verpackung ändern",0],["Einen Einführungsrabatt gewähren",1],["Auch online verkaufen",2],["Eine Plakatkampagne starten",3],["Eine neue Farbe hinzufügen",0],["Das Produkt auf Augenhöhe ins Regal stellen",2]],"ex":"Jeder Entscheid betrifft eines der vier P.","ref":"Lektion 5.4"},{"k":"case","s":"Ein Unternehmen hat ein hervorragendes Produkt zu einem korrekten Preis, gut im Laden platziert, aber niemand kennt es.","q":"Welches P fehlt?","a":["Die Kommunikation","Das Produkt selbst im Regal","Der Verkaufspreis","Der gewählte Verkaufsort"],"ex":"Eine gute Platzierung und ein annehmbarer Preis genügen nicht: Man muss Werbung machen.","ref":"Lektion 5.4"},{"k":"case","s":"Eine Marke für Kinderfrühstücksflocken will, dass die Eltern ihre Schachteln bemerken.","q":"Welches Element des «P» Produkt ist besonders wichtig?","a":["Design und Verpackung","Die Transportkosten","Das Forschungsbudget","Der Ausverkauf am Saisonende"],"ex":"Ein attraktives Design ist entscheidend, um die Aufmerksamkeit der Kunden zu gewinnen.","ref":"Lektion 5.4"},{"k":"tf","q":"Konkurrenz und Rabattforderungen setzen den Preis oft unter Druck.","v":true,"ex":"Der Kurs sagt es.","ref":"Lektion 5.4"},{"k":"tf","q":"Ein Produkt muss nicht ins Sortiment des Unternehmens passen.","v":false,"ex":"Das Produkt muss ins Sortiment passen.","ref":"Lektion 5.4"},{"k":"case","s":"Ein neues Produkt für Fachleute aus dem Baugewerbe soll lanciert werden.","q":"Welche Frage gehört zum «P» Place?","a":["Direkt an Baustellen oder über den Handel verkaufen?","Welche Farbe soll die Verpackung des Produkts erhalten?","Welchen Rabatt gewährt man im Sommerausverkauf?","Welchen Slogan verwendet man für die Radiowerbung?"],"ex":"Man muss bestimmen, wer die Käufer sind und wie man sie am einfachsten erreicht.","ref":"Lektion 5.4"},{"k":"order","q":"Bringen Sie das Vorgehen des Unternehmens zur Festlegung seiner Strategie in die richtige Reihenfolge.","a":["Informationen über den Markt beschaffen","Massnahmen festlegen, um sich durchzusetzen","Sie im Marketing-Mix kombinieren"],"ex":"Der Marketing-Mix stützt sich auf die Informationen über den Markt.","ref":"Lektion 5.4"},{"k":"odd","q":"Was gehört nicht zu den 4 P?","a":["Personal","Produkt","Preis","Kommunikation"],"ex":"Die 4 P: Produkt, Preis, Place (Distribution), Promotion (Kommunikation).","ref":"Lektion 5.4"},{"k":"fill","q":"Die Wahl des Werbeträgers hängt hauptsächlich vom verfügbaren ___ ab.","a":["Budget","Personalbestand","Bestand","Lager"],"ex":"Das Budget bestimmt die möglichen Werbeträger.","ref":"Lektion 5.4"},{"k":"case","s":"Ein Geschäft will seinen Winterbestand loswerden, bevor die Sommerkollektion kommt.","q":"Welches Preisinstrument passt hier?","a":["Der Ausverkauf","Der Einführungspreis","Die Öffentlichkeitsarbeit","Die Verpackung"],"ex":"Der Ausverkauf erlaubt, einen Bestand abzubauen.","ref":"Lektion 5.4"},{"k":"case","s":"Eine Marke organisiert einen Tag der offenen Tür und lädt die Lokalpresse ein.","q":"Welchem Element der Promotion entspricht das?","a":["Die Öffentlichkeitsarbeit","Die Sortimentsstrategie","Die Produktionskosten","Der Einführungspreis"],"ex":"Die Öffentlichkeitsarbeit gehört zur Promotion.","ref":"Lektion 5.4"},{"k":"case","s":"Ein Hersteller lanciert eine Bohrmaschine mit tollem Design, aber sie fällt nach wenigen Wochen oft aus.","q":"Worauf beruht die Vermarktung eines Produkts vor allem?","a":["Auf Nutzen und Qualität","Nur auf seinem tiefen Preis","Nur auf seiner Werbung im Radio","Auf dem Namen seines Herstellers"],"ex":"Der Kurs sagt es zum «P» Produkt.","ref":"Lektion 5.4"},{"k":"case","s":"Ein Lager platziert die Neuheiten an der Stirnseite des Regals, beim Eingang des Geschäfts.","q":"Welches P ist betroffen?","a":["Die Distribution (Place)","Der Preis","Das Produkt","Die Öffentlichkeitsarbeit"],"ex":"Zu entscheiden, wo das Produkt platziert wird, um die Zielgruppe zu erreichen, gehört zur Distribution.","ref":"Lektion 5.4"},{"k":"tf","q":"Der Preis eines Produkts hängt auch von seinen Produktions- und Vertriebskosten ab.","v":true,"ex":"Sowie von den Forschungsausgaben.","ref":"Lektion 5.4"},{"k":"case","s":"Ein Unternehmen lanciert einen Staubsauger mit reduziertem Preis im ersten Monat.","q":"Welches Preisinstrument verwendet es?","a":["Der Einführungspreis","Der Ausverkauf am Saisonende","Die Verpackung","Die Öffentlichkeitsarbeit"],"ex":"Der Einführungspreis zieht die ersten Käufer an.","ref":"Lektion 5.4"},{"k":"qcm","q":"Warum ist der Marketing-Mix für die Strategie wichtig?","a":["Er kombiniert Massnahmen, um sich durchzusetzen","Er ersetzt die Marktforschung vollständig","Er legt jedes Jahr die Löhne des Personals fest","Er dient nur sehr grossen Unternehmen"],"ex":"Die kombinierten 4 P bilden die Marketingstrategie.","ref":"Lektion 5.4"}]},{"code":"M205.5","t":"Die Werbearten","g":"Ich kann zwischen informativer und suggestiver Werbung unterscheiden und ihre Merkmale und Ziele erklären.","col":"amber","ic":"megaphone","ch":[{"k":"qcm","q":"Was ist informative Werbung?","a":["Sie hebt die Merkmale des Produkts hervor","Sie will vor allem ein starkes Gefühl wecken","Sie hat keinen Bezug zum verkauften Produkt","Sie macht sich über Konkurrenzprodukte lustig"],"ex":"Sie stellt die Merkmale des Produkts vor, um zum Kauf anzuregen.","ref":"Lektion 5.5.3"},{"k":"qcm","q":"Was ist suggestive Werbung?","a":["Sie weckt Gefühle, um zum Kauf anzuregen","Sie gibt die genaue Liste der Merkmale an","Sie nennt nur Preis und Gewicht","Sie will nicht verkaufen"],"ex":"Sie kann sogar ohne direkten Bezug zum Produkt sein.","ref":"Lektion 5.5.3"},{"k":"sort","q":"Informative oder suggestive Werbung?","c":["Informativ","Suggestiv"],"it":[["«Waschmittel wirksam ab 30 °C, 40 Waschgänge»",0],["Ein Athlet, der sich im Regen überwindet, am Schluss ein Logo",1],["«Akku für 48 Stunden, Bildschirm 6,5 Zoll»",0],["Eine glückliche Familie im Sonnenuntergang",1],["«Sicherheitsschuhe S3, Stahlkappe, 650 g»",0],["Eine bewegende Musik und ein Slogan über die Freiheit",1]],"ex":"Informativ: Fakten zum Produkt. Suggestiv: Gefühle.","ref":"Lektion 5.5.3"},{"k":"tf","q":"Eine suggestive Werbung kann als originell oder als geschmacklos gelten.","v":true,"ex":"Der Kurs sagt es.","ref":"Lektion 5.5.3"},{"k":"tf","q":"Eine suggestive Werbung hat immer einen direkten Bezug zum Produkt.","v":false,"ex":"Sie kann Gefühle wecken ohne direkten Bezug zum Produkt.","ref":"Lektion 5.5.3"},{"k":"case","s":"Eine Werbung für ein Fleckenmittel zeigt, dass die Kleider dank dem Produkt länger halten.","q":"Um welche Art von Werbung handelt es sich?","a":["Informativ","Suggestiv","Eine Content-Anzeige","Ein Pop-under"],"ex":"Sie hebt ein Merkmal des Produkts hervor.","ref":"Lektion 5.5.3"},{"k":"case","s":"Eine Sportmarke zeigt einen bewegenden Film über die Entschlossenheit einer Athletin, ohne die Merkmale ihrer Schuhe zu erwähnen.","q":"Um welche Art von Werbung handelt es sich?","a":["Suggestiv","Informativ","Ein Banner","Eine E-Mail-Werbung"],"ex":"Sie setzt auf Gefühl und Entschlossenheit.","ref":"Lektion 5.5.3"},{"k":"qcm","q":"Was ist laut Kurs das Ziel der Werbung?","a":["Ein Publikum zum Handeln anregen","Die Mitarbeitenden über die Arbeitszeiten im Lager informieren","Den dem Kunden übergebenen Lieferschein ersetzen","Den Preis der Rohstoffe auf dem Markt festlegen"],"ex":"Ein Kommunikationsmittel, um ein Publikum zu einem bestimmten Verhalten anzuregen.","ref":"Lektion 5.5"},{"k":"match","q":"Ordnen Sie jeder Werbeart ihr Merkmal zu.","p":[["Informativ","Stellt Fakten zum Produkt vor"],["Suggestiv","Setzt auf Gefühle"]],"ex":"Das sind die zwei Arten aus Lektion 5.5.3.","ref":"Lektion 5.5.3"},{"k":"case","s":"Ihr Unternehmen will Lagerchefs einen neuen Handhubwagen verkaufen.","q":"Welche Werbeart passt am besten?","a":["Informativ: Höchstlast, Akkulaufzeit, Preis","Suggestiv: ein Sonnenuntergang ohne Produkt","Keine: Fachleute kaufen nicht","Ein Pop-up, das ihre Website verdeckt"],"ex":"Bei einem technischen Kauf erwarten die Kunden Fakten.","ref":"Lektion 5.5.3 · (Anwendung)"},{"k":"case","s":"Ein Luxusparfüm zeigt einen Schauspieler an einem Strand, ohne vom Duft zu sprechen.","q":"Warum hier eine suggestive Werbung wählen?","a":["Um das Produkt mit einem Gefühl zu verbinden","Weil das Parfüm keine Merkmale hat","Weil das Gesetz verbietet, darüber zu sprechen","Um den Preis des Parfüms zu senken"],"ex":"Die suggestive Werbung weckt Gefühle, um zum Kauf anzuregen.","ref":"Lektion 5.5.3"},{"k":"multi","q":"Woraus besteht ein Inserat?","good":["Bild","Headline (Titel)","Fliesstext","Slogan","Logo"],"bad":["Lieferschein","Lohnabrechnung"],"ex":"Bild, Titel, Fliesstext, Slogan, Produktname und Logo.","ref":"Lektion 5.5.1"},{"k":"match","q":"Ordnen Sie jedem Element eines Inserats seine Definition zu.","p":[["Headline","Der Titel"],["Fliesstext","Die Informationen zum Produkt"],["Slogan","Das Motto, der Leitgedanke"],["Logo","Das Erkennungszeichen der Marke"]],"ex":"Das sind die Elemente aus Lektion 5.5.1.","ref":"Lektion 5.5.1"},{"k":"case","s":"Ein Transportunternehmen beendet jedes seiner Inserate mit dem Satz «Immer pünktlich, überall».","q":"Wie nennt man diesen Satz, der als Motto dient?","a":["Ein Slogan","Eine Headline","Ein Fliesstext","Ein Logo"],"ex":"Der Kurs definiert ihn so.","ref":"Lektion 5.5.1"},{"k":"odd","q":"Was ist kein Element eines Inserats?","a":["Die Losnummer des Bestands","Das Bild","Der Slogan","Das Logo"],"ex":"Die Losnummer dient der Rückverfolgbarkeit, nicht der Werbung.","ref":"Lektion 5.5.1"},{"k":"fill","q":"Die ___ Werbung hebt die Merkmale des Produkts hervor.","a":["informative","suggestive","lügnerische","versteckte"],"ex":"Die informative Werbung stellt Fakten vor.","ref":"Lektion 5.5.3"},{"k":"tf","q":"Die Werbekosten müssen im Verhältnis zum erwarteten Umsatz stehen.","v":true,"ex":"Bemerkung aus Lektion 5.5.3.","ref":"Lektion 5.5.3"},{"k":"case","s":"Ein kleines Unternehmen plant, Produkte für 20 000 Franken zu verkaufen, und will 50 000 Franken für Fernsehwerbung ausgeben.","q":"Was halten Sie davon?","a":["Das steht in keinem Verhältnis zum erwarteten Umsatz","Eine ausgezeichnete Idee, je teurer, desto besser","Das ist für jedes neue Unternehmen Pflicht","Das ist ohne Risiko, weil Werbung immer rentiert"],"ex":"Die Kosten müssen wirtschaftlich tragbar sein.","ref":"Lektion 5.5.3"},{"k":"order","q":"Bringen Sie die übliche Lesereihenfolge eines Inserats in die richtige Reihenfolge.","a":["Das Bild zieht den Blick an","Der Titel packt","Der Text informiert","Slogan und Logo bleiben in Erinnerung"],"ex":"Jedes Element des Inserats spielt eine Rolle.","ref":"Lektion 5.5.1 · (Anwendung)"},{"k":"multi","q":"Welche Formen der Online-Werbung nennt der Kurs?","good":["E-Mail-Werbung","Banner","Content-Anzeigen","Pop-up und Pop-under"],"bad":["Plakat im Tram","Radiospot"],"ex":"Das sind die Formen aus Lektion 5.5.5.","ref":"Lektion 5.5.5"},{"k":"qcm","q":"Was ist eine «Content-Anzeige»?","a":["Eine unauffällige Werbung, kaum vom Inhalt zu unterscheiden","Ein Fenster, das sich nach dem Schliessen der Website öffnet","Ein sehr sichtbares grafisches Banner oben auf der Seite","Ein E-Mail mit einem Link zur Website des Unternehmens"],"ex":"Sie verschmilzt fast mit dem eigentlichen Inhalt der Website.","ref":"Lektion 5.5.5"},{"k":"qcm","q":"Was ist der Unterschied zwischen einem Pop-up und einem Pop-under?","a":["Das Pop-up öffnet sich mit der Website, das Pop-under nach dem Schliessen","Das Pop-up ist gratis, das Pop-under dagegen immer kostenpflichtig","Das Pop-up spielt Ton ab, das Pop-under bleibt dagegen stumm","Zwischen den beiden Werbeformen gibt es keinen Unterschied"],"ex":"Beide sind separate Werbefenster.","ref":"Lektion 5.5.5"},{"k":"case","s":"Die Internetnutzer bemerken die Banner einer Website, die sie täglich besuchen, nicht mehr.","q":"Wie heisst dieser Effekt?","a":["Die Banner Blindness","Das Pop-under-Fenster","Die Content-Anzeige","Die Hover Ad (Overlay)"],"ex":"Das ist ein Gewöhnungseffekt, der Banner weniger wirksam macht.","ref":"Lektion 5.5.5"},{"k":"case","s":"Eine Werbung überdeckt den ganzen Bildschirm einer Nachrichtenseite und zwingt den Leser, sie anzusehen.","q":"Um welche Form handelt es sich?","a":["Eine Hover Ad","Eine Content-Anzeige","Eine E-Mail-Werbung","Ein Slogan"],"ex":"Hover Ads verdecken den Inhalt und erzwingen die Aufmerksamkeit.","ref":"Lektion 5.5.5"},{"k":"multi","q":"Was bringt Werbung im Internet?","good":["Die Wirkung an der Zahl der Klicks messen","Sein Publikum genau ansprechen","Nach erzeugten Klicks bezahlen"],"bad":["Nur ältere Menschen erreichen","Die Wirkung nie messen können"],"ex":"Das sind die drei Vorteile des Kurses.","ref":"Lektion 5.5.5"}]},{"code":"M205.6","t":"Das AIDA-Konzept","g":"Ich kann das AIDA-Konzept (Attention, Interest, Desire, Action) anwenden, um ein wirksames Inserat zu gestalten, das die Aufmerksamkeit der Kunden gewinnt und sie zum Kauf anregt.","col":"emerald","ic":"funnel","ch":[{"k":"order","q":"Bringen Sie die Schritte des AIDA-Konzepts in die richtige Reihenfolge.","a":["Attention","Interest","Desire","Action"],"ex":"Aufmerksamkeit gewinnen, Interesse wecken, Wunsch auslösen, zum Kauf anregen.","ref":"Lektion 5.5.2"},{"k":"match","q":"Ordnen Sie jedem Buchstaben von AIDA sein Ziel zu.","p":[["A – Attention","Die Aufmerksamkeit des Kunden gewinnen"],["I – Interest","Das Interesse wecken"],["D – Desire","Den Wunsch nach Besitz auslösen"],["A – Action","Zum Kauf anregen"]],"ex":"Das ist das AIDA-Konzept aus Lektion 5.5.2.","ref":"Lektion 5.5.2"},{"k":"qcm","q":"Wofür steht das «D» in AIDA?","a":["Desire","Distribution","Design","Dauer"],"ex":"Desire: den Wunsch auslösen, das Produkt zu besitzen.","ref":"Lektion 5.5.2"},{"k":"qcm","q":"Welcher AIDA-Schritt kommt direkt nach der Aufmerksamkeit?","a":["Das Interesse","Der Wunsch","Die Handlung","Die Distribution"],"ex":"Attention → Interest → Desire → Action.","ref":"Lektion 5.5.2"},{"k":"qcm","q":"Warum verwenden die Produzenten das AIDA-Konzept?","a":["Damit die Werbung wirksam ist","Um die Selbstkosten zu berechnen","Um den Bestand im Lager zu organisieren","Um die Löhne des Teams festzulegen"],"ex":"Das ist laut Kurs sein Zweck.","ref":"Lektion 5.5.2"},{"k":"sort","q":"Welchem AIDA-Schritt entspricht jedes Element?","c":["Attention","Interest","Desire","Action"],"it":[["Ein farbiges Schockbild",0],["Drei konkrete Vorteile des Produkts",1],["Ein glücklicher Kunde, der es benutzt",2],["«Bestellen Sie bis Sonntag: −20 %»",3],["Ein überraschender Titel",0],["Ein Knopf «Jetzt kaufen»",3]],"ex":"Packen, informieren, Lust machen, handeln lassen.","ref":"Lektion 5.5.2"},{"k":"case","s":"Ein Inserat für ein E-Bike zeigt ein spektakuläres Foto, gibt aber weder an, wo man es kaufen, noch wie man es bestellen kann.","q":"Welcher AIDA-Schritt fehlt?","a":["Die Handlung","Die Aufmerksamkeit","Das Interesse","Der Wunsch"],"ex":"Ohne klare Aufforderung zum Kauf handelt der Kunde nicht.","ref":"Lektion 5.5.2"},{"k":"case","s":"Ein Plakat eines Lagers zur Suche nach Lernenden ist grau, ohne Bild, mit einem langen Text in kleiner Schrift.","q":"Welcher AIDA-Schritt misslingt von Anfang an?","a":["Die Aufmerksamkeit","Die abschliessende Handlung","Das Interesse","Der Wunsch"],"ex":"Ohne Blickfang bleibt niemand stehen.","ref":"Lektion 5.5.2"},{"k":"case","s":"Sie gestalten ein Inserat für einen Lieferdienst am Samstag. Sie schreiben: «Ihre Pakete auch am Samstag geliefert, ohne Zuschlag».","q":"Welchem AIDA-Schritt dient dieser Text vor allem?","a":["Das Interesse","Die Aufmerksamkeit","Die Handlung","Das Logo"],"ex":"Er stellt einen konkreten Vorteil vor, der Interesse weckt.","ref":"Lektion 5.5.2"},{"k":"case","s":"Das Ende eines Inserats lautet: «Reservieren Sie Ihr Zeitfenster noch heute auf unserer Website».","q":"Welcher AIDA-Schritt wird angestrebt?","a":["Die Handlung","Die Aufmerksamkeit","Das Interesse","Der Wunsch"],"ex":"Man lädt den Kunden ein, zu handeln.","ref":"Lektion 5.5.2"},{"k":"tf","q":"Bei AIDA kommt die Handlung zuletzt.","v":true,"ex":"Attention, Interest, Desire, dann Action.","ref":"Lektion 5.5.2"},{"k":"tf","q":"Nach AIDA muss man zuerst den Wunsch auslösen und dann die Aufmerksamkeit gewinnen.","v":false,"ex":"Die Aufmerksamkeit kommt zuerst.","ref":"Lektion 5.5.2"},{"k":"fill","q":"Das erste «A» in AIDA steht für ___.","a":["Attention","Action","Angebot","Anzeige"],"ex":"Die Aufmerksamkeit des Kunden gewinnen.","ref":"Lektion 5.5.2"},{"k":"odd","q":"Was gehört nicht zum AIDA-Konzept?","a":["Distribution","Attention","Interest","Desire"],"ex":"AIDA: Attention, Interest, Desire, Action.","ref":"Lektion 5.5.2"},{"k":"case","s":"Ein Inserat für Sicherheitsschuhe zeigt einen lächelnden Logistiker nach einem langen Tag, mit trockenen Füssen und ohne Schmerzen.","q":"Welchem AIDA-Schritt dient dieses Bild vor allem?","a":["Der Wunsch","Die Handlung","Die Aufmerksamkeit","Der Preis"],"ex":"Es macht Lust: Man will dasselbe spüren.","ref":"Lektion 5.5.2"},{"k":"multi","q":"Welche Elemente dienen dazu, die Aufmerksamkeit zu gewinnen?","good":["Ein auffälliges Bild","Ein überraschender Titel","Kräftige Farben"],"bad":["Ein Bestellformular","Die allgemeinen Geschäftsbedingungen"],"ex":"Die Aufmerksamkeit gewinnt man zuerst mit Bild und Titel.","ref":"Lektion 5.5.1 · 5.5.2"},{"k":"case","s":"Ein Kunde sieht Ihr Inserat, findet es interessant, hat Lust darauf, findet aber weder Nummer noch Link.","q":"Was muss man ergänzen?","a":["Eine klare Aufforderung mit Link oder Telefon","Ein zweites Bild, grösser als das erste","Einen viel längeren und ausführlicheren Slogan","Einen noch technischeren Text über das Produkt"],"ex":"Der Schritt Action führt den Kunden zum Kauf.","ref":"Lektion 5.5.2"},{"k":"qcm","q":"Welches Element eines Inserats dient oft dem Schritt «Interest»?","a":["Der Fliesstext mit den Vorteilen","Das kleine Logo in der Ecke","Die gewählte Hintergrundfarbe","Der Name der Druckerei, die es gedruckt hat"],"ex":"Der Fliesstext informiert über das Produkt.","ref":"Lektion 5.5.1 · 5.5.2"},{"k":"case","s":"Sie müssen ein Plakat für den Verkauf gebrauchter Paletten Ihres Lagers gestalten.","q":"Welches Inserat hält AIDA am besten ein?","a":["Scharfes Foto, Titel «Paletten ab 5 Franken», Vorteile, Kontakt","Preisliste in kleiner Schrift, ohne Bild und Kontakt","Grosses Foto des Lagers, ohne Text und Kontaktmöglichkeit","Nur das Logo des Unternehmens, in der Mitte auf weissem Grund"],"ex":"Attention (Foto, Titel), Interest (Vorteile), Desire (Preis), Action (Kontakt).","ref":"Lektion 5.5.2 · (Anwendung)"},{"k":"qcm","q":"Wofür steht das «I» in AIDA?","a":["Interest","Bild","Information","Innovation"],"ex":"Interest: das Interesse wecken.","ref":"Lektion 5.5.2"},{"k":"case","s":"Ein Onlineshop zeigt «Nur noch 3 Artikel an Lager!» neben dem Knopf «Bestellen».","q":"Welcher AIDA-Schritt wird verstärkt?","a":["Die Handlung","Die Aufmerksamkeit","Das Interesse","Die Segmentierung"],"ex":"Die Botschaft drängt dazu, sofort zu bestellen.","ref":"Lektion 5.5.2"},{"k":"tf","q":"Ein Inserat, das Aufmerksamkeit gewinnt, aber kein Interesse weckt, hat wenig Chancen zu verkaufen.","v":true,"ex":"Jeder AIDA-Schritt bereitet den nächsten vor.","ref":"Lektion 5.5.2"},{"k":"case","s":"Ein Radiospot für eine Umzugsfirma beginnt mit dem Geräusch von zerbrechendem Geschirr.","q":"Auf welchen AIDA-Schritt zielt dieses Geräusch?","a":["Die Aufmerksamkeit","Die abschliessende Handlung","Der Wunsch","Der angegebene Preis"],"ex":"Ein überraschendes Geräusch gewinnt die Aufmerksamkeit der Zuhörenden.","ref":"Lektion 5.5.2"},{"k":"qcm","q":"Was ist das Endziel des AIDA-Konzepts?","a":["Den Kunden zum Kauf anregen","Über die Geschichte des Unternehmens informieren","Das Publikum einfach zum Lachen bringen","Den Kundendienst ersetzen"],"ex":"Das ganze Vorgehen führt zur Kaufhandlung.","ref":"Lektion 5.5.2"},{"k":"case","s":"Ein Inserat für einen Selbstlager-Service zeigt eine Familie, die dank der Box zu Hause wieder Platz hat.","q":"Welcher AIDA-Schritt wird vor allem bearbeitet?","a":["Der Wunsch","Die Aufmerksamkeit","Die Handlung","Die Distribution"],"ex":"Man zeigt den Nutzen, um Lust zu machen.","ref":"Lektion 5.5.2"}]},{"code":"M205.7","t":"Eine gute Werbung","g":"Ich kann eine Werbung beurteilen, um festzustellen, ob sie originell, wahrheitsgetreu und emotional ansprechend ist, und die Elemente erkennen, die zu ihrer Wirksamkeit beitragen.","col":"sky","ic":"star","ch":[{"k":"multi","q":"Wie muss eine gute Werbung laut Kurs sein?","good":["Originell, aber nicht geschmacklos","Wahrheitsgetreu"],"bad":["Lügnerisch, wenn es verkauft","Um jeden Preis schockierend"],"ex":"Originell ohne Geschmacklosigkeit, und wahrheitsgetreu.","ref":"Lektion 5.5.4"},{"k":"qcm","q":"Was bedeutet «wahrheitsgetreu» bei einer Werbung?","a":["Sie preist nur die tatsächlichen Merkmale des Produkts an","Sie verspricht Wirkungen, die das Produkt nicht wirklich hat","Sie verschweigt absichtlich schwere Mängel des Produkts","Sie kopiert wörtlich die Werbung eines Konkurrenten"],"ex":"Eine gute Werbung preist nur die tatsächlichen Merkmale an.","ref":"Lektion 5.5.4"},{"k":"qcm","q":"Wie beschreibt eine Werbeagentur im Kurs eine gute Werbung?","a":["«Auf den Kopf zielen und das Portemonnaie treffen»","«Immer lauter schreien als die anderen»","«Den Preis zeigen und sonst nichts daneben»","«Das Publikum schockieren, damit man darüber spricht»"],"ex":"Den Verstand ansprechen und Lust zum Kaufen machen.","ref":"Lektion 5.5.4"},{"k":"case","s":"Eine Werbung behauptet, dass eine Crème ohne Anstrengung 10 kg in einer Woche abnehmen lässt.","q":"Welches Kriterium einer guten Werbung wird nicht eingehalten?","a":["Sie ist nicht wahr","Sie ist nicht originell","Sie hat kein Logo","Sie ist viel zu kurz"],"ex":"Eine gute Werbung preist nur die tatsächlichen Merkmale an.","ref":"Lektion 5.5.4"},{"k":"case","s":"Ein Plakat verwendet einen erniedrigenden Witz über eine Gruppe von Menschen, um Getränke zu verkaufen.","q":"Welches Problem hat diese Werbung?","a":["Sie ist geschmacklos","Sie ist zu informativ","Sie erfüllt alle Kriterien","Sie ist zu wahrheitsgetreu"],"ex":"Originell ja, aber nie geschmacklos.","ref":"Lektion 5.5.4"},{"k":"sort","q":"Erfüllt diese Werbung die Kriterien einer guten Werbung?","c":["Ja","Nein"],"it":[["Überraschende und respektvolle Idee",0],["Unmöglich zu haltendes Versprechen",1],["Tatsächliche Merkmale gut hervorgehoben",0],["Schockierendes Bild ohne Bezug zum Produkt",1],["Berührende und wahre Geschichte",0],["Kopie einer Konkurrenzkampagne",1]],"ex":"Originell ohne Geschmacklosigkeit, wahrheitsgetreu und ansprechend.","ref":"Lektion 5.5.4"},{"k":"tf","q":"Eine gute Werbung darf die Qualitäten des Produkts übertreiben, wenn es verkauft.","v":false,"ex":"Sie muss wahrheitsgetreu sein.","ref":"Lektion 5.5.4"},{"k":"tf","q":"Eine originelle Werbung gewinnt leichter Aufmerksamkeit.","v":true,"ex":"Originalität hilft beim AIDA-Schritt Attention.","ref":"Lektion 5.5.4 · 5.5.2"},{"k":"case","s":"Eine Kampagne für einen Lieferdienst erzählt die wahre Geschichte eines Kuriers, der einer älteren Person ein dringendes Medikament bringt.","q":"Welches Kriterium erfüllt diese Werbung besonders?","a":["Sie ist emotional ansprechend","Sie ist geschmacklos und schockierend","Sie lügt über die Dienstleistung","Sie hat keinen Bezug zur Dienstleistung"],"ex":"Ein echtes Gefühl, verbunden mit der Dienstleistung: Die Werbung berührt das Publikum.","ref":"Lektion 5.5.4 · Lernziel M205.7"},{"k":"multi","q":"Welche Elemente tragen zur Wirksamkeit einer Werbung bei?","good":["Eine originelle Idee","Eine wahre Botschaft","Ein positives Gefühl","Eine klare Handlungsaufforderung"],"bad":["Ein unleserlicher Text","Ein falsches Versprechen"],"ex":"Originalität, Wahrheit, Gefühl und Handlung.","ref":"Lektion 5.5.4 · 5.5.2"},{"k":"case","s":"Eine sehr lustige Werbung, über die alle reden, aber niemand erinnert sich an Produkt oder Marke.","q":"Was ist ihr Mangel?","a":["Sie verbindet Gefühl und Produkt nicht","Sie ist viel zu wahrheitsgetreu","Sie ist zu informativ und technisch","Sie hat ein viel zu grosses Logo"],"ex":"Auf den Kopf zielen und das Portemonnaie treffen: Das Publikum muss sich das Produkt merken.","ref":"Lektion 5.5.4"},{"k":"qcm","q":"Warum muss eine Werbung wahrheitsgetreu sein?","a":["Um das Vertrauen der Kunden zu behalten","Damit ihre Herstellung weniger kostet","Damit sie öfter ausgestrahlt wird","Um keinen Slogan zu brauchen"],"ex":"Eine lügnerische Werbung enttäuscht den Kunden und schadet dem Image.","ref":"Lektion 5.5.4"},{"k":"order","q":"Bringen Sie die Beurteilung einer Werbung in die richtige Reihenfolge.","a":["Das Inserat betrachten","Prüfen, ob es wahr ist","Originalität und Geschmack beurteilen","Das ausgelöste Gefühl bewerten","Ein Fazit zur Wirksamkeit ziehen"],"ex":"Man wendet die Kriterien des Kurses eines nach dem anderen an.","ref":"Lektion 5.5.4 · (Anwendung)"},{"k":"odd","q":"Welches Kriterium gehört laut Kurs nicht zu einer guten Werbung?","a":["Lügnerisch sein","Originell sein","Wahrheitsgetreu sein","Nicht geschmacklos sein"],"ex":"Eine gute Werbung ist wahrheitsgetreu.","ref":"Lektion 5.5.4"},{"k":"fill","q":"Eine gute Werbung ist originell, aber nicht ___.","a":["geschmacklos","preiswert","formatfüllend","gedruckt"],"ex":"Formulierung des Kurses.","ref":"Lektion 5.5.4"},{"k":"match","q":"Ordnen Sie jedem Kriterium ein Beispiel zu.","p":[["Originell","Eine überraschende, nie gesehene Idee"],["Wahrheitsgetreu","Echte Zahlen zur Akkulaufzeit"],["Ansprechend","Eine Geschichte, die das Publikum berührt"]],"ex":"Das sind die Kriterien des Lernziels.","ref":"Lektion 5.5.4"},{"k":"case","s":"Eine Werbung für Sicherheitsschuhe gibt an: «zertifiziert S3, Stahlkappe, im Lager getestet». Die Angaben stimmen.","q":"Was kann man über diese Werbung sagen?","a":["Sie ist wahrheitsgetreu und informativ","Sie lügt über die Sicherheit","Sie ist geschmacklos und schockierend","Sie ist vor allem suggestiv und emotional"],"ex":"Sie preist tatsächliche Merkmale an.","ref":"Lektion 5.5.4 · 5.5.3"},{"k":"qcm","q":"Was bedeutet «auf den Kopf zielen» im Satz der Agentur?","a":["Den Verstand überzeugen","Bilder von Gesichtern verwenden","Das Publikum schockieren wollen","Nur Direktoren ansprechen"],"ex":"Das Denken ansprechen, dann Lust zum Kaufen machen.","ref":"Lektion 5.5.4"},{"k":"qcm","q":"Was bedeutet «das Portemonnaie treffen»?","a":["Den Kauf auslösen","Die Steuern erhöhen","Die Löhne senken","Die Werbung bezahlen"],"ex":"Das Endziel einer Werbung ist der Kauf.","ref":"Lektion 5.5.4"},{"k":"case","s":"Ein Transportunternehmen zeigt in seiner Werbung einen «100 % elektrischen» Lastwagen, obwohl seine Flotte noch mit Diesel fährt.","q":"Welches Risiko geht es ein?","a":["Das Vertrauen der Kunden zu verlieren","Einen Werbepreis zu gewinnen","Seine positive Bekanntheit zu steigern","Gar kein Risiko einzugehen"],"ex":"Eine nicht wahrheitsgetreue Werbung schadet Image und Vertrauen.","ref":"Lektion 5.5.4"},{"k":"tf","q":"Eine Online-Werbung lässt sich anhand der Zahl der Klicks beurteilen.","v":true,"ex":"Das Internet erlaubt, die Wirkung über die Klickrate zu kontrollieren.","ref":"Lektion 5.5.5"},{"k":"case","s":"Zwei Banner werden auf einer Website getestet: A erhält 50 Klicks, B 400 Klicks, bei gleicher Zahl von Aufrufen.","q":"Was können Sie daraus schliessen?","a":["B weckt mehr Interesse","A ist das wirksamere der beiden","Die zwei Banner sind gleich","Klicks messen überhaupt nichts"],"ex":"Die Klickrate erlaubt, die Wirkung zu messen.","ref":"Lektion 5.5.5"},{"k":"case","s":"Eine suggestive Werbung zeigt eine herrliche Landschaft und sanfte Musik, um ein Bergmineralwasser zu verkaufen.","q":"Wie beurteilen Sie sie?","a":["Ansprechend und stimmig zum Produkt","Lügnerisch, weil sie eine Landschaft zeigt","Geschmacklos, weil sie schön ist","Nutzlos, weil sie keinen Preis hat"],"ex":"Das Gefühl ist mit dem Produkt verbunden: Die Werbung ist stimmig.","ref":"Lektion 5.5.3 · 5.5.4"},{"k":"qcm","q":"Was ist das Risiko einer originellen, aber geschmacklosen Werbung?","a":["Schockieren und dem Image schaden","Viel zu günstig zu wirken","Für das Publikum zu informativ zu sein","Keinen einprägsamen Slogan zu haben"],"ex":"Geschmacklosigkeit kann sich gegen die Marke wenden.","ref":"Lektion 5.5.4"},{"k":"case","s":"Ihr Chef fragt Sie nach Ihrer Meinung zu einem Plakat für das Lager: originelle Idee, genaue Angaben, aber kein Kontakt angegeben.","q":"Was schlagen Sie vor?","a":["Einen Kontakt zum Handeln hinzufügen","Die Angaben ungenauer machen","Die originelle Idee streichen","Einen geschmacklosen Witz hinzufügen"],"ex":"Eine gute Werbung muss auch zum Handeln führen (AIDA).","ref":"Lektion 5.5.4 · 5.5.2"}]}];
